    /** "Left key: noise cancelling" and the like: which modes each key's noise control cycles through (EarFun's app, getKeyCustomNoiseCancelList). */
    private fun efCycleTitle(key: String): String {
        val rest = key.removePrefix("ef_cycle_")
        val side = if (rest.startsWith("left")) "setting_ef_cycle_left" else "setting_ef_cycle_right"
        val mode = when (rest.substringAfter('_')) {
            "ambient" -> "setting_ef_cycle_ambient"
            "anc" -> "setting_ef_cycle_anc"
            "wind" -> "setting_ef_cycle_wind"
            "adaptive" -> "setting_ef_cycle_adaptive"
            else -> "action_off"
        }
        return t("setting_ef_cycle_row", t(side), t(mode))
    }

