    /**
     * A gesture row of the form touch_<gesture>[_call]_<side> (Nothing's: left, right, whole, dial for the CMF Buds
     * Pro 2's case dial, which is pressed and turned rather than tapped, or case for the Ear (3)'s case button), by its
     * gesture; on headphones the gesture also names the button, roller or slider.
     */
    private fun touchTitle(key: String): String? {
        val side = key.substringAfterLast('_')
        if (!key.startsWith("touch_") || side !in TOUCH_SIDES) return null
        val gesture = key.removePrefix("touch_").removeSuffix("_$side")
        if (side == "case" || side == "dial") return when (gesture) {
            "single" -> t("setting_dial_press")
            "double" -> t("setting_dial_double")
            "triple" -> t("setting_dial_triple")
            "hold" -> t("setting_dial_hold")
            "turn" -> t("setting_dial_turn")
            "double_call" -> t("setting_dial_double_call")
            "triple_call" -> t("setting_dial_triple_call")
            else -> null
        }
        return when (gesture) {
            "single" -> t("setting_touch_single")
            "double" -> t("setting_touch_double")
            "triple" -> t("setting_touch_triple")
            "hold" -> t("setting_touch_hold")
            "double_hold" -> t("setting_touch_double_hold")
            "double_call" -> t("setting_touch_double_call")
            "triple_call" -> t("setting_touch_triple_call")
            "hold_call" -> t("setting_touch_hold_call")
            // The headphones' control button, roller and slider (Nothing's).
            "single_button" -> t("setting_button_press")
            "hold_button" -> t("setting_button_hold")
            "single_roller" -> t("setting_roller_press")
            "hold_roller" -> t("setting_roller_hold")
            "single_slider" -> t("setting_slider")
            else -> null
        }
    }

    /** A Sony general setting's row, by the title the earbuds gave: one of Sony's names, or their own text (SonySession). */
    private fun sonyGeneralTitle(key: String): String? {
        if (!key.startsWith("sony_gs_")) return null
        val title = key.removePrefix("sony_gs_")
        if (title.startsWith("raw:")) return title.removePrefix("raw:")
        return when (title) {
            "TOUCH_PANEL_SETTING" -> t("setting_touch_panel")
            "FACETAP_SETTING", "SELECTABLE_FACETAP_SETTING" -> t("setting_wide_area_tap")
            "SIDETONE_SETTING" -> t("setting_sidetone")
            "TWS_ONE_SIDE_USE_NCASM_SETTING" -> t("setting_noise_one_earbud")
            "TAP_SENSITIVITY_SETTING" -> t("setting_tap_sensitivity")
            "VOICE_GUIDANCE_SETTING" -> t("setting_voice_guidance")
            else -> title.lowercase().removeSuffix("_setting").replace('_', ' ').replaceFirstChar { it.uppercase() }
        }
    }

    /** One of the headphones' buttons and a gesture on it, from a key such as `ef_button_nc_hold_call` (EarFun's). */
    private fun buttonTitle(key: String): String? {
        if (!key.startsWith("ef_button_")) return null
        val rest = key.removePrefix("ef_button_")
        val button = when (rest.substringBefore('_')) {
            "plus" -> "setting_ef_button_plus"
            "minus" -> "setting_ef_button_minus"
            else -> "setting_ef_button_nc"
        }
        val gesture = when (rest.substringAfter('_')) {
            "double" -> "setting_ef_press_double"
            "hold" -> "setting_ef_press_hold"
            "single_call" -> "setting_ef_press_call"
            "hold_call" -> "setting_ef_hold_call"
            else -> "setting_ef_press"
        }
        return t("setting_ef_button", t(button), t(gesture))
    }

