    /** A JBL customized button page gesture ("jbl_p5_<place>_<gesture>"): where it is and the gesture. */
    private fun jblP5Title(key: String): String? {
        if (!key.startsWith("jbl_p5_")) return null
        val (place, gesture) = key.removePrefix("jbl_p5_").split("_", limit = 2).takeIf { it.size == 2 } ?: return null
        val where = when (place) {
            "left" -> "setting_jbl_place_left"
            "right" -> "setting_jbl_place_right"
            "multiFunctionalButton" -> "setting_jbl_place_button"
            "ancButton" -> "setting_jbl_place_anc_button"
            "touchPanel" -> "setting_jbl_place_touch_panel"
            else -> return null
        }
        val what = when (gesture) {
            "tap" -> "setting_jbl_gesture_tap"
            "doubleTap" -> "setting_jbl_gesture_double_tap"
            "tripleTap" -> "setting_jbl_gesture_triple_tap"
            "tapAndHold" -> "setting_jbl_gesture_tap_hold"
            "press" -> "setting_jbl_gesture_press"
            "doublePress" -> "setting_jbl_gesture_double_press"
            "triplePress" -> "setting_jbl_gesture_triple_press"
            "pressAndHold" -> "setting_jbl_gesture_press_hold"
            else -> return null
        }
        return t("setting_jbl_place_gesture", t(where), t(what))
    }


    private val DIAL_GESTURES = setOf("single", "double", "triple", "hold", "turn", "double_call", "triple_call")
    private val TOUCH_GESTURES = setOf(
        "single", "double", "triple", "hold", "double_hold", "double_call", "triple_call", "hold_call",
        "single_button", "hold_button", "single_roller", "hold_roller", "single_slider",
    )

    /** True when [touchTitle] has words for the row: a touch row of a known side and gesture, decided without a composition. */
    private fun isTouchRow(key: String): Boolean {
        val side = key.substringAfterLast('_')
        if (!key.startsWith("touch_") || side !in TOUCH_SIDES) return false
        val gesture = key.removePrefix("touch_").removeSuffix("_$side")
        return gesture in if (side == "case" || side == "dial") DIAL_GESTURES else TOUCH_GESTURES
    }

    /** The screens' words for a brand row's [option]. */
    fun optionLabel(key: String, option: String): String = when {
        key.startsWith("jb_") -> when {
            option == "off" -> t("action_off")
            option.startsWith("min_") -> t("setting_power_off_timer_minutes", option.removePrefix("min_").toInt())
            option.startsWith("db_") -> t("jb_fixed_db", option.removePrefix("db_"))
            else -> JabraLabels.OPTION[option]?.let { t(it) } ?: option.replace('_', ' ')
        }
        key == "sh_nautilus_anc" -> t(when (option) { "off" -> "action_off"; "airplane" -> "setting_sh_nautilus_airplane"; "outdoor" -> "setting_sh_nautilus_outdoor"; else -> "setting_sh_nautilus_home" })
        key == "sh_nautilus_anc_state" -> t(when (option) { "off" -> "action_off"; "on" -> "setting_anc"; else -> "setting_sh_adaptive_anc" })
        key == "sh_multi_function" -> t(if (option == "EQModes") "setting_sh_multi_eq" else "action_voice_assistant")
        key.startsWith("sh_nautilus_") && key != "sh_nautilus_anc" && key != "sh_nautilus_anc_state" && key != "sh_nautilus_preset" && key != "sh_nautilus_anc_middle" -> t(when (option) {
            "off" -> "action_off"; "on" -> "setting_sh_nautilus_on"; "low" -> "setting_level_low"; "medium" -> "setting_level_medium"; "high" -> "setting_level_high"
            "near" -> "setting_sh_nautilus_near"; "far" -> "setting_sh_nautilus_far"; "rumble" -> "setting_sh_nautilus_rumble"; "thump" -> "setting_sh_nautilus_thump"; else -> "setting_sh_nautilus_voice"
